1	// Fresh isolated browser capture. No production/profile-wide browser configuration.
2	import { spawn } from 'node:child_process';
3	import { access, mkdir, readFile, writeFile, mkdtemp, realpath, rm } from 'node:fs/promises';
4	import { resolve, join, relative, sep } from 'node:path';
5	import { tmpdir } from 'node:os';
6	import { serve, rendererRoot, hash } from './server.mjs';
7	
8	const option = name => { const i = process.argv.indexOf(name); return i < 0 ? null : process.argv[i + 1]; };
9	const project = resolve(option('--project') || join(rendererRoot, '..'));
10	const output = option('--out');
11	if (!output) throw new Error('Use --out NEW_DIRECTORY to retain a fresh capture');
12	const out = resolve(output);
13	await mkdir(out, { recursive: false });
14	let browser = option('--browser');
15	if (!browser) {
16	  for (const file of [join(process.env.PROGRAMFILES || '', 'Google/Chrome/Application/chrome.exe'), join(process.env['ProgramFiles(x86)'] || '', 'Microsoft/Edge/Application/msedge.exe')]) {
17	    try { await access(file); browser = file; break; } catch { /* Try next installed browser. */ }
18	  }
19	}
20	if (!browser) throw new Error('No local Chromium browser found; pass --browser PATH');
21	const profileParent = await realpath(tmpdir());
22	const profile = await mkdtemp(join(profileParent, 'pixl-render-'));
23	const rendererFiles = Object.fromEntries(await Promise.all(['server.mjs', 'capture.mjs', 'index.html', 'view.mjs', 'check.py'].map(async name => [name, hash(await readFile(join(rendererRoot, name)))])));
24	let observed;
25	const running = await serve(project, report => { if (observed) throw new Error('Duplicate capture'); observed = report; });
26	const args = ['--headless=new', '--disable-gpu', '--hide-scrollbars', '--no-first-run', '--no-default-browser-check', '--disable-background-networking', '--force-device-scale-factor=1', `--user-data-dir=${profile}`, '--window-size=1280,1000', '--virtual-time-budget=4000', '--run-all-compositor-stages-before-draw', `--screenshot=${join(out, 'destination.png')}`, `${running.url}/?capture=1`];
27	await writeFile(join(out, 'launch.json'), JSON.stringify({ browser, args, project, node: process.version, scope: 'Isolated local fixture renderer' }, null, 2) + '\n');
28	let processResult;
29	try {
30	  processResult = await new Promise((yes, no) => {
31	    const child = spawn(browser, args, { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
32	    let stdout = '', stderr = '';
33	    child.stdout.on('data', chunk => { stdout += chunk; }); child.stderr.on('data', chunk => { stderr += chunk; });
34	    const timer = setTimeout(() => { child.kill(); no(new Error('Browser capture exceeded 45 seconds')); }, 45_000);
35	    child.once('error', error => { clearTimeout(timer); no(error); });
36	    child.once('exit', code => { clearTimeout(timer); yes({ code, stdout, stderr }); });
37	  });
38	  await writeFile(join(out, 'browser-process.json'), JSON.stringify(processResult, null, 2) + '\n');
39	  if (processResult.code !== 0 || !observed) throw new Error('Browser did not return a complete capture');
40	  const screenshot = await readFile(join(out, 'destination.png'));
41	  let index = 0;
42	  for (const item of [...observed.views, ...observed.timeline]) if (item.png) {
43	    const bytes = Buffer.from(item.png.split(',')[1], 'base64');
44	    const name = `view-${String(index++).padStart(3, '0')}.png`;
45	    await writeFile(join(out, name), bytes); item.image = { path: name, sha256: hash(bytes) }; delete item.png;
46	  }
47	  observed.served_files = Object.fromEntries(running.served);
